insert into change_headers (id, ts) values (71, '2026-11-01') on duplicate key update ts = values(ts);
insert into change_descriptions (id, lang, description) values (71, 'ru', 'В калькуляторах Гравитона и Терраформера на вкладке «Формы жизни» появилось поле «Бонус класса» в блоке «Коллекционер» — для значения «Коллекционер, всего» из панели форм жизни в игре. Оно учитывается для класса Коллекционер и повышает его бонус к энергии и к грузоподъёмности малых и больших транспортов.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (71, 'en', 'The Graviton and Terraformer calculators have a new "Class bonus" field in the "Collector" block on the LifeForms tab, for the "Collector, Total" value from the game''s life form panel. It counts for the Collector class and raises its energy bonus and its Small and Large Cargo capacity bonus.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (71, 'pt', 'As calculadoras de Gravitação e de Terra-formador têm um novo campo «Bônus de classe» no bloco «Colecionador» do separador Formas de vida, para o valor «Colecionador, total» do painel de formas de vida do jogo. Conta para a classe Colecionador e aumenta o seu bónus de energia e de capacidade de carga dos Cargueiros Pequenos e Grandes.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (71, 'de', 'Die Graviton- und Terraformer-Rechner haben im Reiter Lebensformen ein neues Feld „Klassenbonus“ im Block „Kollektor“ für den Wert „Kollektor, Gesamt“ aus dem Lebensformen-Panel im Spiel. Es zählt für die Kollektor-Klasse und erhöht deren Energiebonus sowie den Ladekapazitätsbonus von Kleinen und Großen Transportern.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (71, 'pl', 'W kalkulatorach Grawitonów i Terraformera na karcie Formy życia pojawiło się pole „Premia klasy” w bloku „Zbieracz” na wartość „Zbieracz, łącznie” z panelu form życia w grze. Uwzględniane jest dla klasy Zbieracz i zwiększa jej premię do energii oraz do ładowności Małych i Dużych transporterów.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (71, 'es', 'Las calculadoras de Gravitón y Terraformer tienen un nuevo campo «Bonificación de clase» en el bloque «Recolector» de la pestaña Formas de vida, para el valor «Recolector, total» del panel de formas de vida del juego. Cuenta para la clase Recolector y aumenta su bonificación de energía y de capacidad de carga de las Naves de Carga Pequeñas y Grandes.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (71, 'fr', 'Les calculateurs de Graviton et de Terraformeur ont un nouveau champ « Bonus de classe » dans le bloc « Collecteur » de l''onglet Formes de vie, pour la valeur « Collecteur, total » du panneau des formes de vie du jeu. Il compte pour la classe Collecteur et augmente son bonus d''énergie et son bonus de capacité de fret des Petits et Grands transporteurs.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (71, 'it', 'I calcolatori di Gravitonica e Terraformer hanno un nuovo campo «Bonus classe» nel blocco «Collector» della scheda Forme di vita, per il valore «Collector, totale» del pannello delle forme di vita del gioco. Vale per la classe Collector e ne aumenta il bonus all''energia e alla capacità di carico dei Cargo Leggeri e Pesanti.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (71, 'nl', 'De Graviton- en Terravormer-berekeningen hebben een nieuw veld "Klassebonus" in het blok "Collector" op het tabblad Levensvormen, voor de waarde "Collector, totaal" uit het levensvormenpaneel in het spel. Het telt voor de Collector-klasse en verhoogt haar energiebonus en de laadcapaciteitsbonus van kleine en grote vrachtschepen.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (71, 'sk', 'Kalkulátory pre Graviton a Terraformer majú na karte Formy života nové pole „Bonus triedy“ v bloku „Collector“ pre hodnotu „Collector, celkom“ z panelu foriem života v hre. Započíta sa pre triedu Collector a zvyšuje jej bonus k energii a k nosnosti Malých a Veľkých transportérov.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (71, 'tr', 'Gravitasyon ve Terraformer hesaplayıcılarının Yaşam Formları sekmesindeki "Koleksiyoncu" bloğunda, oyundaki yaşam formu panelindeki "Koleksiyoncu, toplam" değeri için yeni bir "Sınıf bonusu" alanı var. Koleksiyoncu sınıfı için geçerlidir ve bu sınıfın enerji bonusunu ile Küçük ve Büyük Nakliye kargo kapasitesi bonusunu artırır.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (71, 'bs', 'Kalkulatori gravitona i terraformera imaju na kartici Oblici života novo polje „Bonus klase“ u bloku „Sakupljač“ za vrijednost „Sakupljač, ukupno“ iz panela oblika života u igri. Računa se za klasu Sakupljač i povećava njen bonus na energiju i na kapacitet tereta malih i velikih transportera.') on duplicate key update description = values(description);
